  // Show secure authentication message
  function showAuthMessage(message, type) {
    // Remove any existing message
    const existingMessage = document.getElementById('auth-message');
    if (existingMessage) {
      existingMessage.remove();
    }

    // Create new message element
    const messageEl = document.createElement('div');
    messageEl.id = 'auth-message';
    messageEl.className = `auth-message ${type}`;
    messageEl.textContent = SecurityUtils.sanitizeHTML(message);

    // Style based on type
    messageEl.style.cssText = `
            position: fixed;
            top: 20px;
            right: 20px;
            padding: 15px 20px;
            border-radius: 8px;
            z-index: 10000;
            font-weight: 500;
            animation: slideIn 0.3s ease;
            max-width: 400px;
            word-wrap: break-word;
        `;

    if (type === 'success') {
      messageEl.style.backgroundColor = '#d4edda';
      messageEl.style.color = '#155724';
      messageEl.style.border = '1px solid #c3e6cb';
    } else if (type === 'error') {
      messageEl.style.backgroundColor = '#f8d7da';
      messageEl.style.color = '#721c24';
      messageEl.style.border = '1px solid #f5c6cb';
    }

    document.body.appendChild(messageEl);

    // Auto-hide after 5 seconds
    setTimeout(() => {
      if (messageEl && messageEl.parentNode) {
        messageEl.remove();
      }
    }, 5000);
  }

  // Show secure login modal
  function showLoginModalSecure() {
    // Remove any existing modal
    closeAllModals();

