// Security Utilities - Input Sanitization and Validation
(function() {
  'use strict';

  // XSS Prevention - HTML Sanitization
  window.SecurityUtils = {

    // Sanitize HTML content to prevent XSS attacks
    sanitizeHTML: function(input) {
      if (!input || typeof input !== 'string') return '';

      const div = document.createElement('div');
      div.textContent = input;
      return div.innerHTML;
    },

    // Sanitize and validate user name
    sanitizeName: function(name) {
      if (!name || typeof name !== 'string') return '';

      // Remove HTML tags and limit length
      const sanitized = this.sanitizeHTML(name);

      // Only allow alphanumeric characters, spaces, and basic punctuation
      const cleaned = sanitized.replace(/[^a-zA-Z0-9\s\-_.]/g, '');

      // Limit length to prevent abuse
      return cleaned.substring(0, 50).trim();
    },

    // Sanitize and validate email
    sanitizeEmail: function(email) {
      if (!email || typeof email !== 'string') return '';

      const sanitized = this.sanitizeHTML(email);
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

      return emailRegex.test(sanitized) ? sanitized : '';
    },

    // Sanitize message content
    sanitizeMessage: function(message) {
      if (!message || typeof message !== 'string') return '';

      // Remove HTML tags but preserve line breaks
      const sanitized = this.sanitizeHTML(message);

      // Limit message length
      const maxLength = 1000;
      const truncated = sanitized.substring(0, maxLength);

      // Remove potentially dangerous patterns
      const cleaned = truncated
        .replace(/javascript:/gi, '')
        .replace(/data:/gi, '')
        .replace(/vbscript:/gi, '')
        .replace(/on\w+=/gi, '');

      return cleaned.trim();
    },

    // Validate and sanitize URLs
    sanitizeURL: function(url) {
      if (!url || typeof url !== 'string') return '';

      try {
        const urlObj = new URL(url);

        // Only allow HTTP and HTTPS protocols
        if (urlObj.protocol !== 'http:' && urlObj.protocol !== 'https:') {
          return '';
        }

        return urlObj.toString();
      } catch (error) {
        return '';
      }
    },

    // Create safe DOM element with text content
    createSafeElement: function(tagName, textContent, className) {
      const element = document.createElement(tagName);
      if (textContent) {
        element.textContent = this.sanitizeHTML(textContent);
      }
      if (className) {
        element.className = className;
      }
      return element;
    },

    // Safe innerHTML replacement
    safeInnerHTML: function(element, content) {
      if (!element || !content) return;

      // Clear existing content
      element.innerHTML = '';

      // Parse content and create safe elements
      const div = document.createElement('div');
      div.textContent = content;
      element.appendChild(div);
    },

    // Validate authentication token format
    validateTokenFormat: function(token) {
      if (!token || typeof token !== 'string') return false;

      // Basic JWT format validation (3 parts separated by dots)
      const parts = token.split('.');
      if (parts.length !== 3) return false;

      // Check for basic Base64 format
      const base64Regex = /^[A-Za-z0-9+/]*={0,2}$/;
      return parts.every(part => base64Regex.test(part));
    },

    // Rate limiting for actions
    rateLimiter: function(key, maxAttempts = 5, timeWindow = 60000) {
      if (!window.rateLimitCache) {
        window.rateLimitCache = new Map();
      }

      const now = Date.now();
      const userAttempts = window.rateLimitCache.get(key) || [];

      // Remove old attempts outside time window
      const recentAttempts = userAttempts.filter(time => now - time < timeWindow);

      if (recentAttempts.length >= maxAttempts) {
        return false; // Rate limit exceeded
      }

      // Add current attempt
      recentAttempts.push(now);
      window.rateLimitCache.set(key, recentAttempts);

      return true; // Action allowed
    },

    // Generate CSRF token
    generateCSRFToken: function() {
      const array = new Uint8Array(32);
      crypto.getRandomValues(array);
      return Array.from(array, byte => byte.toString(16).padStart(2, '0')).join('');
    },

    // Validate CSRF token
    validateCSRFToken: function(token) {
      const stored = sessionStorage.getItem('csrf_token');
      return stored && stored === token;
    },

    // Set CSRF token
    setCSRFToken: function() {
      const token = this.generateCSRFToken();
      sessionStorage.setItem('csrf_token', token);
      return token;
    },

    // Content Security Policy helper
    setCSPHeaders: function() {
      const meta = document.createElement('meta');
      meta.httpEquiv = 'Content-Security-Policy';
      meta.content = 'default-src \'self\'; script-src \'self\' \'unsafe-inline\' accounts.google.com; style-src \'self\' \'unsafe-inline\' fonts.googleapis.com; font-src \'self\' fonts.gstatic.com; img-src \'self\' data: https:; connect-src \'self\' https://api.example.com';
      document.head.appendChild(meta);
    }
  };

  // Initialize CSRF protection
  window.SecurityUtils.setCSRFToken();

  // Set CSP headers if not already set
  if (!document.querySelector('meta[http-equiv="Content-Security-Policy"]')) {
    window.SecurityUtils.setCSPHeaders();
  }

  console.log('Security utilities loaded and initialized');
})();

// Enhanced Social Feed with Authentication and Chat Support
(function() {
  'use strict';

  console.log('Enhanced Social Feed Loading...');

  // Social feed state
  window.socialFeed = {
    posts: [],
    chatRooms: new Map(),
    activeChat: null,
    isLoading: false,
    currentFilter: 'all' // 'all', 'following', 'local'
  };

  // Initialize social feed
  window.initSocialFeed = function() {
    console.log('Initializing social feed...');

    // Load posts
    loadSocialPosts();

    // Setup real-time updates
    setupRealTimeUpdates();

    // Render initial feed
    renderSocialFeed();
  };

  // Load social posts
  async function loadSocialPosts() {
    if (window.socialFeed.isLoading) return;

    window.socialFeed.isLoading = true;

    try {
      const response = await fetch('/api/social/posts', {
        headers: {
          'Authorization': `Bearer ${window.authState.token || ''}`
        }
      });

      const data = await response.json();

      if (data.success) {
        window.socialFeed.posts = data.posts || [];
      } else {
        // Use demo data if no backend
        window.socialFeed.posts = getDemoPosts();
      }

      renderSocialFeed();
    } catch (error) {
      console.error('Error loading social posts:', error);
      // Use demo data as fallback
      window.socialFeed.posts = getDemoPosts();
      renderSocialFeed();
    } finally {
      window.socialFeed.isLoading = false;
    }
  }

  // Get demo posts
  function getDemoPosts() {
    return [
      {
        id: 'demo-1',
        author: {
          name: 'Demo User',
          avatar: 'https://via.placeholder.com/40x40?text=D',
          isAdmin: false
        },
        content: 'Welcome to the social feed! This is a demo post.',
        timestamp: Date.now() - 3600000, // 1 hour ago
        likes: 5,
        comments: 2,
        type: 'post',
        gameId: null
      },
      {
        id: 'demo-2',
        author: {
          name: 'Game Host',
          avatar: 'https://via.placeholder.com/40x40?text=G',
          isAdmin: true
        },
        content: 'Basketball game at Central Park - 3 spots left!',
        timestamp: Date.now() - 1800000, // 30 minutes ago
        likes: 12,
        comments: 8,
        type: 'game',
        gameId: 'game-123',
        gameInfo: {
          sport: 'Basketball',
          location: 'Central Park',
          time: '7:00 PM',
          spotsLeft: 3
        }
      }
    ];
  }

  // Render social feed
  function renderSocialFeed() {
    const feedContainer = document.getElementById('social-feed-container');
    if (!feedContainer) return;

    if (window.socialFeed.posts.length === 0) {
      feedContainer.innerHTML = `
                <div class="empty-feed">
                    <h3>No posts yet</h3>
                    <p>Be the first to share something!</p>
                </div>
            `;
      return;
    }

    const postsHTML = window.socialFeed.posts.map(post => `
            <div class="social-post" data-post-id="${post.id}">
                <div class="post-header">
                    <img src="${post.author.avatar}" alt="${post.author.name}" class="author-avatar">
                    <div class="author-info">
                        <span class="author-name">${post.author.name}</span>
                        ${post.author.isAdmin ? '<span class="admin-badge">Admin</span>' : ''}
                        <span class="post-time">${formatTime(post.timestamp)}</span>
                    </div>
                </div>

                <div class="post-content">
                    ${post.content}
                    ${post.type === 'game' ? renderGameInfo(post.gameInfo) : ''}
                </div>

                <div class="post-actions">
                    <button onclick="likePost('${post.id}')" class="like-btn">
                        👍 ${post.likes}
                    </button>
                    <button onclick="showComments('${post.id}')" class="comment-btn">
                        💬 ${post.comments}
                    </button>
                    ${post.type === 'game' ? `<button onclick="joinGameChat('${post.gameId}')" class="chat-btn">💬 Chat</button>` : ''}
                </div>
            </div>
        `).join('');

    feedContainer.innerHTML = postsHTML;
  }

  // Render game info
  function renderGameInfo(gameInfo) {
    if (!gameInfo) return '';

    return `
            <div class="game-info">
                <div class="game-details">
                    <strong>🏀 ${gameInfo.sport}</strong>
                    <span>📍 ${gameInfo.location}</span>
                    <span>🕐 ${gameInfo.time}</span>
                    <span class="spots-left">${gameInfo.spotsLeft} spots left</span>
                </div>
                <button onclick="joinGame('${gameInfo.id}')" class="join-game-btn">Join Game</button>
            </div>
        `;
  }

  // Format time
  function formatTime(timestamp) {
    const now = Date.now();
    const diff = now - timestamp;

    if (diff < 3600000) { // Less than 1 hour
      const minutes = Math.floor(diff / 60000);
      return `${minutes}m ago`;
    } else if (diff < 86400000) { // Less than 24 hours
      const hours = Math.floor(diff / 3600000);
      return `${hours}h ago`;
    } else {
      const days = Math.floor(diff / 86400000);
      return `${days}d ago`;
    }
  }

  // Like post
  window.likePost = async function(postId) {
    if (!window.authState.isAuthenticated) {
      window.showLoginModal();
      return;
    }

    try {
      const response = await fetch(`/api/social/posts/${postId}/like`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${window.authState.token}`,
          'Content-Type': 'application/json'
        }
      });

      const data = await response.json();

      if (data.success) {
        // Update post likes in UI
        const post = window.socialFeed.posts.find(p => p.id === postId);
        if (post) {
          post.likes = data.likes;
          renderSocialFeed();
        }
      }
    } catch (error) {
      console.error('Error liking post:', error);
      // Demo behavior
      const post = window.socialFeed.posts.find(p => p.id === postId);
      if (post) {
        post.likes++;
        renderSocialFeed();
      }
    }
  };

  // Join game chat
  window.joinGameChat = function(gameId) {
    if (!window.authState.isAuthenticated) {
      window.showLoginModal();
      return;
    }

    // Create or join chat room for the game
    const chatRoom = `game-${gameId}`;
    window.socialFeed.activeChat = chatRoom;

    // Initialize chat room if not exists
    if (!window.socialFeed.chatRooms.has(chatRoom)) {
      window.socialFeed.chatRooms.set(chatRoom, {
        messages: [],
        participants: []
      });
    }

    // Show chat modal
    showChatModal(chatRoom);
  };

  // Show chat modal
  function showChatModal(chatRoom) {
    const modal = document.createElement('div');
    modal.id = 'chat-modal';
    modal.style.cssText = `
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0,0,0,0.5);
            display: flex;
            justify-content: center;
            align-items: center;
            z-index: 10000;
        `;

    modal.innerHTML = `
            <div style="background: white; width: 90%; max-width: 600px; height: 80%; border-radius: 12px; display: flex; flex-direction: column;">
                <div style="padding: 1rem; border-bottom: 1px solid #eee; display: flex; justify-content: space-between; align-items: center;">
                    <h3>Game Chat</h3>
                    <button onclick="closeChatModal()" style="background: none; border: none; font-size: 24px; cursor: pointer;">×</button>
                </div>

